import {escapeHtml as h,number} from './domain.js';
import {planetArt,badge,civilizationBadge,shipArt} from './art.js';
import {recentBattlesView} from './reports.js';
const pop=n=>new Intl.NumberFormat('en',{notation:'compact',maximumFractionDigits:1}).format(Number(n)||0);
const fields=[['soldiers','Soldats'],['scouts','Scouts'],['bombers','Bombardiers'],['fighters','Destroyers']];
export function sumForces(forces){return forces.reduce((t,f)=>{for(const k of ['scouts','bombers','fighters'])t[k]+=Number(f[k])||0;t.ground+=Number(f.ground_soldiers)||0;t.embarked+=Number(f.soldiers)||0;t.soldiers=t.ground+t.embarked;if(f.kind==='fleet'&&Number(f.scouts)+Number(f.bombers)+Number(f.fighters)>0)t.fleets++;return t;},{soldiers:0,scouts:0,bombers:0,fighters:0,ground:0,embarked:0,fleets:0});}
export function forceCamps(p){const side=p.stance==='attack'?'attack':'defend',forces=p.forces||[];return {own:sumForces(forces.filter(f=>f.is_own)),allies:sumForces(forces.filter(f=>!f.is_own&&f.mission===side)),enemies:sumForces(forces.filter(f=>!f.is_own&&f.mission!==side))};}
const hasForces=t=>fields.some(([key])=>Number(t?.[key])>0);
function foreignCampRows(title,tone,p,detailed){
 const side=p.stance==='attack'?'attack':'defend';
 const forces=(p.forces||[]).filter(f=>!f.is_own&&(tone==='allied'?f.mission===side:f.mission!==side));
 return ['elys','vael','khar'].map(race=>{const total=sumForces(forces.filter(f=>(f.race||p.race)===race));return hasForces(total)?forcesRow(title,total,tone,race,detailed,true):'';}).join('');
}
function forcesRow(title,t,tone,race,detailed,showRace=false){return `<div class="overview-force ${tone}"><b class="force-label">${title}${showRace?`<span class="force-race">${badge('race',race)}${h(race.charAt(0).toUpperCase()+race.slice(1))}</span>`:''}</b><span class="force-count">${number(t.fleets)} flotte${t.fleets>1?'s':''}</span><div class="overview-units">${fields.map(([k,label])=>`<span title="${label}" aria-label="${number(t[k])} ${label}">${k==='soldiers'?badge('race',race):shipArt(race,k==='scouts'?'scout':k==='bombers'?'bomber':'fighter')}<strong>${number(t[k])}</strong>${detailed?`<small>${label}</small>`:''}</span>`).join('')}</div>${detailed?`<small>${number(t.ground)} au sol · ${number(t.embarked)} embarqués</small>`:''}</div>`;}
function traits(p){return `<div class="overview-traits">${badge('race',p.race)}${badge('resource',p.resource)}<span>${badge('pop',p.race)}${pop(p.population)}</span><span>${civilizationBadge()}<b>${number(p.civilization)}</b></span></div>`;}
function worldCard(p,data,detailed){
 const camps=forceCamps(p),own=(data.planets||[]).find(w=>w.id===p.id),jobs=(data.jobs||[]).filter(j=>j.planet_id===p.id),busy=jobs.filter(j=>j.kind!=='factory').length;
 const total=Number(p.trade_capacity)||0,used=Number(p.trade_exploited)||0,energy=Math.max(0,Number(own?.energy)||0),energyMax=Math.max(1,Number(own?.energy_max)||10);
 const status=p.is_own?'Sous contrôle':p.stance==='mixed'?'Attaque & défense':p.stance==='attack'?'En attaque':'En défense';
 return `<article class="overview-world ${p.stance==='attack'||p.stance==='mixed'?'hostile-world':''}"><button class="overview-world-link" data-page="fleets" data-military-location="${h(p.id)}" aria-label="Gérer les forces sur ${h(p.name)}"><img class="overview-planet" src="${planetArt(p.appearance||p.race+'_'+p.resource)}" alt="" width="82" height="82"><span><small>${status}</small><h3>${h(p.name)}</h3>${traits(p)}</span><span class="overview-arrow" aria-hidden="true">↗</span></button>${p.is_own&&!detailed?`<div class="overview-trade"><span>Commerce <b>${number(used)} / ${number(total)}</b></span><progress value="${used}" max="${Math.max(1,total)}" aria-label="Capacités commerciales exploitées"></progress></div><div class="overview-trade overview-energy"><span>Énergie <b>${number(energy)} / ${number(energyMax)}</b></span><progress value="${Math.min(energy,energyMax)}" max="${energyMax}" aria-label="Énergie disponible"></progress></div>`:''}<div class="overview-camps">${forcesRow('Vos forces',camps.own,'own',p.race,detailed)}${foreignCampRows(p.stance==='mixed'?'Autres en défense':'Alliés','allied',p,detailed)}${foreignCampRows(p.stance==='mixed'?'Autres en attaque':'Ennemis','hostile',p,detailed)}</div>${detailed&&own?`<div class="overview-industry"><span><b>${number(own.factories)}</b> usines <small>· ${number(Math.max(0,own.factories-busy))} libres</small></span><div>${jobs.length?['scout','bomber','fighter','factory'].map(kind=>{const batch=jobs.filter(j=>j.kind===kind);if(!batch.length)return '';const first=batch.reduce((a,b)=>a.finishes_at<b.finishes_at?a:b);return `<span class="production-chip"><b>${batch.length}</b> ${({scout:'scout(s)',bomber:'bombardier(s)',fighter:'destroyer(s)',factory:'usine'})[kind]} <small>${batch.some(j=>j.paused_at)?'En pause':`Prochaine fin : ${h(new Intl.DateTimeFormat('fr-FR',{dateStyle:'short',timeStyle:'short'}).format(new Date(first.finishes_at)))}`}</small></span>`;}).join(''):'<small>Aucune production en cours</small>'}</div></div>`:''}</article>`;
}
export function commandPlanetOverview(data){const worlds=(data?.locations||[]).filter(p=>p.is_own);return `<section class="world-overview"><div class="military-section-heading"><h2>Planètes sous contrôle</h2><span>${worlds.length} mondes</span></div><div class="overview-grid">${worlds.map(p=>worldCard(p,data,false)).join('')}</div></section>`;}
export function militaryOverviewView(data,pending){return `<div class="military-overview">${pending?'<div class="document-panel"><p>Un ordre attend sa confirmation.</p><button id="retry-military" class="secondary">Vérifier cet ordre</button></div>':''}<div class="military-section-heading"><h2>Vos positions militaires</h2><button class="secondary" data-page="transit">Flottes en transit →</button></div><div class="overview-grid">${(data?.locations||[]).map(p=>worldCard(p,data,true)).join('')||'<p class="empty">Aucune position militaire.</p>'}</div>${recentBattlesView(data)}</div>`;}
